/**
 * Smoke Test Configuration
 * Provides limited event processing for quick verification of the ingestion pipeline
 */

import type { RawEventInput } from '@eventpulse/shared';

// Configuration constants
export const SMOKE_TEST_CONFIG = {
  // Maximum events per venue/arranger group
  MAX_EVENTS_PER_VENUE: 10,

  // Maximum total events per source (safety guard)
  MAX_EVENTS_PER_SOURCE: 50,

  // Queue name for smoke test events
  QUEUE_NAME: 'raw_events_smoke',

  // Concurrency for normalizer in smoke test
  CONCURRENCY: 5,
};

/**
 * Event limiter - limits events per venue/group
 * Groups events by venue_name (or source if no venue)
 * Takes only first N events per group
 */
export function limitEventsPerVenue(
  events: any[],
  maxPerVenue: number = SMOKE_TEST_CONFIG.MAX_EVENTS_PER_VENUE,
  maxTotal: number = SMOKE_TEST_CONFIG.MAX_EVENTS_PER_SOURCE
): any[] {
  const venueGroups = new Map<string, any[]>();

  // Group events by venue
  for (const event of events) {
    const venueKey = event.venue_name || event.venue || event.source || 'unknown';
    if (!venueGroups.has(venueKey)) {
      venueGroups.set(venueKey, []);
    }
    venueGroups.get(venueKey)!.push(event);
  }

  // Take first N from each group
  const limited: any[] = [];
  for (const [venue, venueEvents] of venueGroups) {
    const venueLimited = venueEvents.slice(0, maxPerVenue);
    limited.push(...venueLimited);

    if (venueEvents.length > maxPerVenue) {
      console.log(`[smoke-test] Venue "${venue}": ${venueEvents.length} → ${maxPerVenue} events`);
    }
  }

  // Apply total limit
  if (limited.length > maxTotal) {
    console.log(`[smoke-test] Total events: ${limited.length} → ${maxTotal} events`);
    return limited.slice(0, maxTotal);
  }

  return limited;
}

/**
 * Check if running in smoke test mode
 */
export function isSmokeTestMode(): boolean {
  return process.argv.includes('--mode=smoke') || process.argv.includes('--smoke');
}

/**
 * Format smoke test summary
 */
export function formatSmokeTestSummary(results: {
  source: string;
  fetched: number;
  afterLimit: number;
  queued: number;
  normalized: number;
  upserted: number;
}[]): string {
  const lines: string[] = [];
  lines.push('\n╔══════════════════════════════════════════════════════════════════╗');
  lines.push('║                    SMOKE TEST RESULTS                          ║');
  lines.push('╠══════════════════════════════════════════════════════════════════╣');
  lines.push('║ Source          │ Fetched │ Limit    │ Queued   │ Norm  │ Upsert║');
  lines.push('╠─────────────────┼─────────┼──────────┼──────────┼───────┼───────╣');

  for (const r of results) {
    const name = r.source.padEnd(14).slice(0, 14);
    lines.push(
      `║ ${name} │ ${String(r.fetched).padStart(7)} │ ${String(r.afterLimit).padStart(8)} │ ${String(r.queued).padStart(8)} │ ${String(r.normalized).padStart(5)} │ ${String(r.upserted).padStart(5)}║`
    );
  }

  lines.push('╚══════════════════════════════════════════════════════════════════╝');

  // Totals
  const totals = results.reduce(
    (acc, r) => ({
      fetched: acc.fetched + r.fetched,
      afterLimit: acc.afterLimit + r.afterLimit,
      queued: acc.queued + r.queued,
      normalized: acc.normalized + r.normalized,
      upserted: acc.upserted + r.upserted,
    }),
    { fetched: 0, afterLimit: 0, queued: 0, normalized: 0, upserted: 0 }
  );

  lines.push(`\nTotal: Fetched=${totals.fetched}, After Limit=${totals.afterLimit}, Queued=${totals.queued}, Normalized=${totals.normalized}, Upserted=${totals.upserted}`);

  return lines.join('\n');
}
